class PromptGenerator {
    constructor() {
        this.constraints = [];
        this.commands = [];
        this.resources = [];
        this.performanceEvaluation = [];
        this.responseFormat = {
            response: "verbal response to user",
            thoughts: {
                text: "thought",
                reasoning: "reasoning",
                plan: "- short bulleted\n- list that conveys\n- long-term plan",
                criticism: "constructive self-criticism",
            },
            command: {
                name: "command name",
                args: { "arg name": "value" },
            },
        };
    }
    addConstraint(constraint) {
        this.constraints.push(constraint);
    }
    addCommand(commandLabel, commandName, args = {}) {
        const command = {
            label: commandLabel,
            name: commandName,
            args: args,
        };
        this.commands.push(command);
    }
    generateCommandString(command) {
        const argsString = Object.entries(command.args)
            .map(([key, value]) => `"${key}": "${value}"`)
            .join(", ");
        return `${command.label}: "${command.name}", args: {${argsString}}`;
    }
    addResource(resource) {
        this.resources.push(resource);
    }
    addPerformanceEvaluation(evaluation) {
        this.performanceEvaluation.push(evaluation);
    }
    generateNumberedList(items, itemType = "list") {
        if (itemType === "command") {
            return items
                .map((item, index) => `${index + 1}. ${this.generateCommandString(item)}`)
                .join("\n");
        }
        else {
            return items.map((item, index) => `${index + 1}. ${item}`).join("\n");
        }
    }
    generatePromptString() {
        const formattedResponseFormat = "```json\n" + JSON.stringify(this.responseFormat, null, 4) + "\n```";
        return (`Constraints:\n${this.generateNumberedList(this.constraints)}\n\n` +
            `Commands:\n${this.generateNumberedList(this.commands, "command")}\n\n` +
            `Resources:\n${this.generateNumberedList(this.resources)}\n\n` +
            `Performance Evaluation:\n${this.generateNumberedList(this.performanceEvaluation)}\n\n` +
            "You should first respond with a clear summary of thoughts to articulate to user, followed by detailed thoughts in JSON format as described below \n" +
            `Response Format:\n\n${formattedResponseFormat} \n\nEnsure the response can be parsed by Python json.loads\n---\n\n`);
    }
}

function getPrompt() {
    const promptGenerator = new PromptGenerator();
    promptGenerator.addConstraint("~4000 word limit for short term memory. Your short term memory is short, so immediately save important information to files.");
    promptGenerator.addConstraint("If you are unsure how you previously did something or want to recall past events, thinking about similar events will help you remember.");
    promptGenerator.addConstraint("You are an artificial intelligence voice assistant. The assistant always gives helpful, detailed, and polite answers to the human's questions.");
    promptGenerator.addConstraint('Exclusively use the commands listed in double quotes e.g. "command name"');
    const commands = [
        // ["Google Search", "google", { input: "<search>" }],
        // ["Screenshot", "screenshot", {}],
        ["no_action", "no_action", {}],
        ["done", "done", {}],
        ["get_current_datetime", "get_current_datetime", {}],
    ];
    for (const [commandLabel, commandName, args] of commands) {
        promptGenerator.addCommand(commandLabel, commandName, args);
    }
    promptGenerator.addResource("Internet access for searches and information gathering.");
    promptGenerator.addResource("Long Term memory management.");
    promptGenerator.addResource("LLM powered Agents for delegation of simple tasks.");
    promptGenerator.addResource("File output.");
    promptGenerator.addPerformanceEvaluation("Continuously review and analyze your actions to ensure you are performing to the best of your abilities.");
    promptGenerator.addPerformanceEvaluation("Constructively self-criticize your big-picture behavior constantly.");
    promptGenerator.addPerformanceEvaluation("Reflect on past decisions and strategies to refine your approach.");
    promptGenerator.addPerformanceEvaluation("Every command has a cost, so be smart and efficient. Aim to complete tasks in the least number of steps.");
    return promptGenerator.generatePromptString();
}

